package com.bank.coupon.service;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

// Generates all DISTINCT subsets when the input contains duplicates.
public class DupSubsetsService {
    private static final Logger log = Logger.getLogger(DupSubsetsService.class.getName());

    public List<List<Integer>> distinctBundles(int[] coupons) {
        Arrays.sort(coupons); // equal values become adjacent
        List<List<Integer>> subsets = new ArrayList<>();
        subsets.add(new ArrayList<>());

        int previousRoundStart = 0;
        for (int c = 0; c < coupons.length; c++) {
            int start = 0;
            // On a duplicate, extend ONLY the previous round's subsets.
            if (c > 0 && coupons[c] == coupons[c - 1]) {
                start = previousRoundStart;
            }
            int size = subsets.size();
            previousRoundStart = size;
            for (int i = start; i < size; i++) {
                List<Integer> copy = new ArrayList<>(subsets.get(i));
                copy.add(coupons[c]);
                subsets.add(copy);
            }
            int coupon = coupons[c];
            log.fine(() -> "After coupon " + coupon + " total distinct = " + subsets.size());
        }
        log.info(() -> "Generated " + subsets.size() + " distinct bundles");
        return subsets;
    }
}
